import Foundation
import MLX
import MLXFastCore
import MLXNN
import MLXLMCommon

/// Gemma 4 rotary position embedding kernels generated by MetalTile
/// (https://github.com/0xClandestine/metaltile). Each kernel is specialized
/// at build time for one of the four (sliding/full) × (Q/K) configurations
/// that appear in Gemma 4 31B:
///
/// | Layer type | head_dim | rotary_pairs | head_dim_half | theta_base |
/// |------------|----------|--------------|---------------|------------|
/// | sliding    | 256      | 128          | 128           | 10 000     |
/// | full       | 512      | 64           | 256           | 1 000 000  |
///
/// Q (32 heads) and K (16 heads sliding, 4 heads full) use the same kernel —
/// only the dispatch grid differs. The kernel writes to every element of
/// `out`: rotated for `i < rotary_pairs`, passthrough for the unrotated
/// tail, so the host doesn't need a separate `qk.copy()` step.
///
/// The wrapping class transposes the input to the kernel's expected
/// [B, L, n_heads, head_dim] contiguous layout (one extra copy), dispatches
/// the kernel, and transposes the result back to the caller's
/// [B, n_heads, L, head_dim] strided layout (zero-copy).

// MARK: - Metal kernels

/// Sliding-window Q — head_dim=256, full RoPE, row_stride = 32*256 = 8192.
private let gemma4SlidingQPrefill = MLXFast.metalKernel(
    name: "gemma4_mt_sliding_q_partial_rope_prefill_bf16",
    inputNames: ["qk", "positions"],
    outputNames: ["out"],
    source: """
        constexpr uint head_dim = 256u;
        constexpr uint half_rotary = 128u;
        constexpr uint head_dim_half = 128u;
        constexpr uint row_stride = 8192u;
        constexpr float theta_base = 10000f;
        uint v_r = thread_position_in_grid.x;
        uint v_i = thread_position_in_grid.z;
        auto v3 = row_stride;
        auto v5 = head_dim;
        uint v_head = thread_position_in_grid.y;
        auto v6 = v_head * v5;
        auto v_head_base = ((v_r * v3) + v6);
        auto v_dim_lo = v_head_base + v_i;
        auto v9 = head_dim_half;
        auto v10 = v_head_base + v9;
        auto v_dim_hi = v10 + v_i;
        auto v12 = qk[v_dim_lo];
        float v_x_lo = static_cast<float>(v12);
        auto v14 = qk[v_dim_hi];
        float v_x_hi = static_cast<float>(v14);
        auto v16 = half_rotary;
        auto v17 = v16 > v_i;
        if (v17) {
            auto v21 = theta_base;
            auto v22 = log2(v21);
            float v_half_f = static_cast<float>(v16);
            auto v26 = positions[v_r];
            auto v_inv_freq = exp2((((-static_cast<float>(v_i)) * v22) / v_half_f));
            auto v_theta = (static_cast<float>(v26) * v_inv_freq);
            auto v_cos_t = cos(v_theta);
            auto v_sin_t = sin(v_theta);
            auto v32 = v_x_hi * v_sin_t;
            auto v35 = v_x_hi * v_cos_t;
            bfloat v37 = bfloat(((v_x_lo * v_cos_t) - v32));
            out[v_dim_lo] = bfloat(v37);
            bfloat v38 = bfloat(((v_x_lo * v_sin_t) + v35));
            out[v_dim_hi] = bfloat(v38);
        } else {
            bfloat v39 = bfloat(v_x_lo);
            out[v_dim_lo] = bfloat(v39);
            bfloat v40 = bfloat(v_x_hi);
            out[v_dim_hi] = bfloat(v40);
        }
        """,
    header: "using namespace metal;",
    ensureRowContiguous: true
)

