// MARK: - Dispatcher

private func gemma4PickRopeKernel(headDim: Int, nHeads: Int) -> MLXFast.MLXFastKernel {
    switch (headDim, nHeads) {
    case (256, 32): return gemma4SlidingQPrefill
    case (256, 16): return gemma4SlidingKPrefill
    case (512, 32): return gemma4FullQPrefill
    case (512, 4):  return gemma4FullKPrefill
    default:
        fatalError(
            "gemma4_mt partial RoPE: unsupported (head_dim=\(headDim), n_heads=\(nHeads)) — expected (256, 32|16) or (512, 32|4)"
        )
    }
}

private func gemma4PickHeadDimHalf(headDim: Int) -> Int {
    headDim / 2
}

// MARK: - Public RoPE layer

public final class Gemma4PartialRoPEMetalTile: Module, OffsetLayer, ArrayOffsetLayer {
    public let dims: Int
    public let traditional: Bool = false

    public init(dims: Int) {
        self.dims = dims
        super.init()
    }

    public func callAsFunction(_ x: MLXArray, offset: Int = 0) -> MLXArray {
        precondition(x.ndim == 4, "gemma4_mt RoPE: expected 4D input, got \(x.ndim)D")
        precondition(x.dtype == .bfloat16, "gemma4_mt RoPE: expected bf16 input, got \(x.dtype)")
        let nHeads = x.shape[1]
        let L = x.shape[2]
        let headDim = x.shape[3]
        precondition(headDim == dims, "gemma4_mt RoPE: head_dim mismatch (\(headDim) vs \(dims))")
        precondition(headDim == 256 || headDim == 512, "gemma4_mt RoPE: unsupported head_dim=\(headDim)")

        let contiguousIn = x.transposed(0, 2, 1, 3).contiguous()
        precondition(headDim == dims, "gemma4_mt RoPE: head_dim mismatch (\(headDim) vs \(dims))")
        precondition(headDim == 256 || headDim == 512, "gemma4_mt RoPE: unsupported head_dim=\(headDim)")

        let positions = gemma4BuildPositions(start: UInt32(offset), length: L)

        let out = gemma4DispatchPrefill(
            input: contiguousIn,
            positions: positions,
            nHeads: nHeads,
            headDim: headDim
        )

        return out.transposed(0, 2, 1, 3)
    }

    public func callAsFunction(_ x: MLXArray, offset: MLXArray) -> MLXArray {
        precondition(x.ndim == 4, "gemma4_mt RoPE: expected 4D input, got \(x.ndim)D")
        precondition(x.dtype == .bfloat16, "gemma4_mt RoPE: expected bf16 input, got \(x.dtype)")
        let nHeads = x.shape[1]
        let L = x.shape[2]
        let headDim = x.shape[3]
        precondition(headDim == dims, "gemma4_mt RoPE: head_dim mismatch (\(headDim) vs \(dims))")
        precondition(headDim == 256 || headDim == 512, "gemma4_mt RoPE: unsupported head_dim=\(headDim)")
        precondition(offset.size == L, "gemma4_mt RoPE: offset.size (\(offset.size)) must equal L (\(L))")

        let contiguousIn = x.transposed(0, 2, 1, 3).contiguous()
        precondition(headDim == dims, "gemma4_mt RoPE: head_dim mismatch (\(headDim) vs \(dims))")
        precondition(headDim == 256 || headDim == 512, "gemma4_mt RoPE: unsupported head_dim=\(headDim)")
        precondition(offset.size == L, "gemma4_mt RoPE: offset.size (\(offset.size)) must equal L (\(L))")

        let positions: MLXArray
        if offset.ndim == 0 {
            let start = offset.item(UInt32.self)
            positions = gemma4BuildPositions(start: start, length: L)
        } else {
            positions = offset.asType(.uint32)
        }

        let out = gemma4DispatchPrefill(
            input: contiguousIn,
            positions: positions,
            nHeads: nHeads,
            headDim: headDim
        )

        return out.transposed(0, 2, 1, 3)
    }
}



private func gemma4DispatchPrefill(
    input: MLXArray,
    positions: MLXArray,
    nHeads: Int,
    headDim: Int
) -> MLXArray {
    let L = input.shape[1]
    let headDimHalf = gemma4PickHeadDimHalf(headDim: headDim)
    let kernel = gemma4PickRopeKernel(headDim: headDim, nHeads: nHeads)

    return kernel(
        [input, positions],
        grid: (L, nHeads, headDimHalf),
        threadGroup: (1, 1, 1),
        outputShapes: [input.shape],
        outputDTypes: [.bfloat16]
    )[0]
}

private func gemma4BuildPositions(start: UInt32, length: Int) -> MLXArray {
    var data = [UInt32](repeating: 0, count: length)
    for i in 0..<length {
        data[i] = start &+ UInt32(i)
    }
    return data.withUnsafeBufferPointer { ptr in
        MLXArray(
            UnsafeRawBufferPointer(ptr),
            [length],
            type: UInt32.self
        )
    }
}
